const nextDocNumber = `-- name: NextDocNumber :one

insert into doc_counters (prefix, year, last_no)
values ($1, $2, 1)
on conflict (prefix, year) do update set last_no = doc_counters.last_no + 1
returning last_no
`

type NextDocNumberParams struct {
	Prefix string
	Year   int32
}

// Документы движения, их строки и сканы (СО-1).
// Счётчик растёт в транзакции документа: при откате номер не теряется.
func (q *Queries) NextDocNumber(ctx context.Context, arg NextDocNumberParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextDocNumber, arg.Prefix, arg.Year)
	var last_no int32
	err := row.Scan(&last_no)
	return last_no, err
}

